1	-- Correções pós-QA do fluxo de bipagem:
2	--
3	-- FIX 1 — estoque_lotes chaveado por (lote, produto, LOJA).
4	-- Antes o UPDATE/INSERT de tg_movimentacoes_sync_estoque_lotes ignorava loja_id →
5	-- bips de lojas diferentes do mesmo lote caíam numa única linha com loja_id NULL,
6	-- invisível na visão por loja ("só contagem geral, sem lote").
7	--
8	-- FIX 2 — bipagem idempotente.
9	-- bipar_lote_scanner ignorava o resultado de bipar_etiqueta; re-bipar a mesma etiqueta
10	-- (já 'recebida'/'em_transito') lançava a movimentação de novo → contagem dupla.
11	-- Agora respeita ok=false (bip duplicado) e devolve o item como 'já contado', sem relançar.
12	
13	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
14	RETURNS trigger
15	LANGUAGE plpgsql
16	SECURITY DEFINER
17	SET search_path = public
18	AS $$
19	BEGIN
20	  IF NEW.motivo IS DISTINCT FROM 'scanner_lote' THEN
21	    RETURN NEW;
22	  END IF;
23	
24	  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
25	    RETURN NEW;
26	  END IF;
27	
28	  -- Guarda: alteração em estoque_lotes via movimentação não dispara reconciliação fantasma.
29	  PERFORM set_config('app.skip_lote_reconcile', '1', true);
30	
31	  IF NEW.tipo_movimentacao = 'entrada' THEN
32	    UPDATE public.estoque_lotes
33	       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
34	     WHERE lote_id = NEW.lote_id
35	       AND produto_id = NEW.produto_master_id
36	       AND loja_id = NEW.loja_id;
37	
38	  ELSIF NEW.tipo_movimentacao = 'saida' THEN
39	    UPDATE public.estoque_lotes
40	       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
41	     WHERE lote_id = NEW.lote_id
42	       AND produto_id = NEW.produto_master_id
43	       AND loja_id = NEW.loja_id;
44	  END IF;
45	
46	  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
47	    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
48	    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
49	  END IF;
50	
51	  RETURN NEW;
52	END;
53	$$;
54	
55	CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(
56	    p_loja_id integer,
57	    p_tipo text,
58	    p_itens jsonb
59	)
60	RETURNS jsonb
61	LANGUAGE plpgsql
62	SECURITY DEFINER
63	SET search_path TO 'public'
64	AS $$
65	DECLARE
66	    v_usuario_id integer;
67	    v_item jsonb;
68	    v_id text;
69	    v_pid integer;
70	    v_uid text;
71	    v_lote_id uuid;
72	    v_qty numeric;
73	    v_disp numeric;
74	    v_interna numeric;
75	    v_tipo_embalagem text;
76	    v_embalagem_nome text;
77	    v_lote text;
78	    v_payload jsonb;
79	    v_bip jsonb;
80	    v_saldo_anterior numeric;
81	    v_saldo_novo numeric;
82	    v_motivo text;
83	    v_observacoes text;
84	    v_resultados jsonb := '[]'::jsonb;
85	    v_ok integer := 0;
86	    v_err integer := 0;
87	BEGIN
88	    BEGIN
89	        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
90	    EXCEPTION WHEN OTHERS THEN
91	        v_usuario_id := NULL;
92	    END;
93	
94	    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
95	    LOOP
96	        v_id := v_item->>'id';
97	        BEGIN
98	            v_pid := (v_item->>'pid')::integer;
99	            v_uid := NULLIF(v_item->>'uid', '');
100	            v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
101	            v_qty := (v_item->>'qty')::numeric;
102	            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
103	            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
104	            v_lote := NULLIF(v_item->>'lote', '');
105	            v_payload := v_item->'payload';
106	
107	            IF v_uid IS NOT NULL THEN
108	                BEGIN
109	                    v_bip := public.bipar_etiqueta(
110	                        v_uid,
111	                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
112	                        jsonb_build_object(
113	                            'loja_id', p_loja_id,
114	                            'referencia_tipo', 'scanner_lote',
115	                            'payload', v_payload
116	                        )
117	                    );
118	                EXCEPTION WHEN OTHERS THEN
119	                    v_bip := NULL;
120	                END;
121	
122	                -- IDEMPOTENCIA: etiqueta ja contada nesta etapa → nao lanca de novo.
123	                IF v_bip IS NOT NULL AND COALESCE((v_bip->>'ok')::boolean, true) = false THEN
124	                    v_resultados := v_resultados || jsonb_build_object(
125	                        'id', v_id, 'ok', false,
126	                        'erro', COALESCE(NULLIF(v_bip->>'erro',''), 'Etiqueta já contada nesta etapa')
127	                    );
128	                    v_err := v_err + 1;
129	                    CONTINUE;
130	                END IF;
131	
132	                -- QTY AUTORITATIVA: o que a caixa realmente tem.
133	                SELECT quantidade_disponivel, quantidade_interna
134	                  INTO v_disp, v_interna
135	                  FROM etiquetas_qr
136	                 WHERE uid = v_uid;
137	                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
138	            END IF;
139	
140	            IF v_qty IS NULL OR v_qty <= 0 THEN
141	                RAISE EXCEPTION '%', CASE WHEN p_tipo='entrada'
142	                    THEN 'Sem quantidade para dar entrada'
143	                    ELSE 'Container ja vazio — nada para dar saida' END;
144	            END IF;
145	
146	            SELECT COALESCE(quantidade_atual, 0)
147	              INTO v_saldo_anterior
148	              FROM estoque
149	             WHERE produto_master_id = v_pid
150	               AND loja_id = p_loja_id;
151	
152	            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);
153	
154	            IF p_tipo = 'entrada' THEN
155	                v_saldo_novo := v_saldo_anterior + v_qty;
156	            ELSE
157	                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
158	            END IF;
159	
160	            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
161	            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
162	                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
163	                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
164	                || ' · Lote ' || COALESCE(v_lote, '—');
165	
166	            INSERT INTO movimentacoes (
167	                produto_master_id, tipo_movimentacao, quantidade,
168	                quantidade_anterior, quantidade_nova, motivo, observacoes,
169	                data_movimentacao, loja_id, lote_id, etiqueta_qr_uid, usuario_id
170	            ) VALUES (
171	                v_pid, p_tipo, v_qty,
172	                v_saldo_anterior, v_saldo_novo, v_motivo, v_observacoes,
173	                now(), p_loja_id, v_lote_id, v_uid, v_usuario_id
174	            );
175	
176	            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', true);
177	            v_ok := v_ok + 1;
178	
179	        EXCEPTION WHEN OTHERS THEN
180	            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', false, 'erro', SQLERRM);
181	            v_err := v_err + 1;
182	        END;
183	    END LOOP;
184	
185	    RETURN jsonb_build_object(
186	        'ok', true,
187	        'processados', v_ok,
188	        'falhas', v_err,
189	        'resultados', v_resultados
190	    );
191	END;
192	$$;
