1	-- Fix em bipar_etiqueta: no backfill, se o lote_uuid do payload nao existe em lotes,
2	-- resolve por codigo+validade via find_or_create_lote ou usa NULL.
3	-- Antes: INSERT com UUID morto -> FK rejeitava -> movimentacoes FK cascateava erro.
4	CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
5	 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
6	AS $function$
7	DECLARE
8	  v_etiqueta public.etiquetas_qr%ROWTYPE;
9	  v_user_id uuid := auth.uid();
10	  v_user_nome text; v_status_anterior text; v_status_novo text; v_loja_id integer;
11	  v_alertas jsonb := '[]'::jsonb; v_referencia_tipo text; v_referencia_id text;
12	  v_payload jsonb; v_pid_text text; v_pid_int integer; v_lote_uuid uuid;
13	  v_produto_nome text; v_lote_codigo text; v_lote_validade date; v_qty_interna numeric;
14	BEGIN
15	  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
16	    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa); END IF;
17	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
18	  v_loja_id := NULLIF(p_contexto->>'loja_id','')::integer;
19	  v_referencia_tipo := p_contexto->>'referencia_tipo'; v_referencia_id := p_contexto->>'referencia_id';
20	  v_payload := p_contexto->'payload';
21	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
22	  IF NOT FOUND THEN
23	    IF v_payload IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill'); END IF;
24	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
25	    IF v_pid_text IS NULL OR v_pid_text = '' THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto'); END IF;
26	    v_pid_int := v_pid_text::integer;
27	    v_lote_uuid := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
28	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
29	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
30	    -- Resolve lote_id seguro: UUID morto -> tenta por codigo+validade -> NULL
31	    IF v_lote_uuid IS NOT NULL THEN
32	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
33	      IF NOT FOUND THEN
34	        v_lote_codigo  := NULLIF(COALESCE(v_payload->>'lote', v_payload->>'lc'), '');
35	        v_lote_validade := NULLIF(COALESCE(v_payload->>'val', v_payload->>'v'), '')::date;
36	        IF v_lote_codigo IS NOT NULL AND v_lote_validade IS NOT NULL THEN
37	          v_lote_uuid := public.find_or_create_lote(v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL);
38	        ELSE v_lote_uuid := NULL; END IF;
39	      END IF;
40	    END IF;
41	    INSERT INTO public.etiquetas_qr (uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna, quantidade_disponivel, consumida_inteira, produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot, loja_origem_id, loja_atual_id, status, tipo_embalagem, foi_separada, separada_at, separada_por, foi_conferida, conferida_at, conferida_por, backfilled, qr_payload)
42	    VALUES (p_uid, v_pid_int, v_lote_uuid, COALESCE(v_payload->>'emb', v_payload->>'n'), v_qty_interna, v_qty_interna, false, v_produto_nome, v_lote_codigo, v_lote_validade, NULL, v_loja_id, CASE p_etapa WHEN 'separacao' THEN 'gerada' WHEN 'conferencia' THEN 'gerada' WHEN 'entrada' THEN 'recebida' WHEN 'saida' THEN 'em_transito' WHEN 'consumo' THEN 'consumida' WHEN 'descarte' THEN 'descartada' END, COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'), (p_etapa = 'separacao'), CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END, (p_etapa = 'conferencia'), CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END, true, v_payload) RETURNING * INTO v_etiqueta;
43	    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
44	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload));
45	    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', NULL, 'status_novo', v_etiqueta.status, 'alertas', v_alertas, 'backfilled', true);
46	  END IF;
47	  v_status_anterior := v_etiqueta.status;
48	  IF v_etiqueta.status = 'descartada' THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada' || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')' ELSE '' END, 'etiqueta', to_jsonb(v_etiqueta)); END IF;
49	  IF v_etiqueta.lote_validade_snapshot IS NOT NULL AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN v_alertas := v_alertas || jsonb_build_array(format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))); END IF;
50	  IF p_etapa = 'separacao' THEN
51	    IF v_etiqueta.foi_separada THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid), 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior); END IF;
52	    UPDATE public.etiquetas_qr SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
53	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
54	    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
55	  END IF;
56	  IF p_etapa = 'conferencia' THEN
57	    IF v_etiqueta.foi_conferida THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid), 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior); END IF;
58	    UPDATE public.etiquetas_qr SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
59	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
60	    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
61	  END IF;
62	  v_status_novo := CASE p_etapa
63	    WHEN 'saida' THEN CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito' ELSE NULL END
64	    WHEN 'entrada' THEN CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida' WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida' ELSE NULL END
65	    WHEN 'consumo' THEN 'consumida'
66	    WHEN 'descarte' THEN 'descartada'
67	  END;
68	  IF v_status_novo IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior), 'etiqueta', to_jsonb(v_etiqueta)); END IF;
69	  UPDATE public.etiquetas_qr SET status = v_status_novo, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
70	  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
71	  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_novo, 'alertas', v_alertas, 'backfilled', false);
72	END;
73	$function$;
