9	// Retry com backoff exponencial
10	async function retryWithBackoff<T>(
11	  fn: () => Promise<T>,
12	  maxRetries: number = 3,
13	  baseDelay: number = 1000
14	): Promise<T> {
15	  let lastError: Error;
16	  for (let attempt = 0; attempt <= maxRetries; attempt++) {
17	    try {
18	      return await fn();
19	    } catch (error) {
20	      lastError = error as Error;
21	      if (attempt === maxRetries) throw lastError;
22	      const delay = baseDelay * Math.pow(2, attempt);
23	      console.log(`❌ Tentativa ${attempt + 1} falhou: ${lastError.message}. Retentando em ${delay}ms...`);
24	      await new Promise(resolve => setTimeout(resolve, delay));
25	    }
26	  }
27	  throw lastError!;
28	}
